    12	import ProtectedText from "../Blocks/ProtectedText"
    13	import { ChatMessage } from "./Message"
    14	import MessageViewer from "./MessageViewer"
    15	import { RenderJson } from "./RenderJson"
    16	
    17	const checkIsMessage = (obj) => {
    18	  return (
    19	    typeof obj?.text === "string" ||
    20	    typeof obj?.content === "string" ||
    21	    Array.isArray(obj?.content) ||
    22	    typeof obj?.functionCall === "object" ||
    23	    typeof obj?.function_call === "object" ||
    24	    typeof obj?.toolCalls === "object" ||
    25	    typeof obj?.tool_calls === "object"
    26	  )
    27	}
    28	
    29	export default function SmartViewer({
    30	  data,
    31	  error,
    32	  compact = false,
    33	}: {
    34	  data: any
    35	  error?: any
    36	  compact?: boolean
    37	}) {
    38	  const parsed = useMemo(() => {
    39	    if (!data) return null
    40	    if (typeof data === "string" && data?.startsWith("{")) {
    41	      try {
    42	        return JSON.parse(data)
    43	      } catch (e) {
    44	        return data
    45	      }
    46	    }
    47	
    48	    return data
    49	  }, [data])
    50	
    51	  const isObject = typeof parsed === "object"
    52	
    53	  const isMessages = useMemo(() => {
    54	    if (!parsed) return false
    55	    return Array.isArray(parsed)
    56	      ? parsed.every(checkIsMessage)
    57	      : checkIsMessage(parsed)
    58	  }, [parsed])
