    68	                ? compact
    69	                  ? error.message || error.stack
    70	                  : error.stack
    71	                : typeof error === "object"
    72	                  ? JSON.stringify(error, null, 2)
    73	                  : error,
    74	          }}
    75	          compact={compact}
    76	        />
    77	      )}
    78	
    79	      {data && (
    80	        <ProtectedText>
    81	          {isObject ? (
    82	            isMessages ? (
